/* The painting this site sits on, the way Monet Shot frames a take.
   The page becomes a sheet with rounded corners, the painting fills the margin around it.
   Off with ?record (Monet Shot adds its own painting when you record), with ?bare, and when the
   page is shown inside a frame. Swap painting.webp for another to change it; delete the
   <script src="./backdrop/backdrop.js"> line in index.html to drop it. */
(function () {
  var q = new URLSearchParams(location.search), d = document.documentElement;
  if (q.has('record') || q.has('bare')) return;
  try { if (window.top !== window.self && !q.has('backdrop')) return; } catch (e) { return; }
  var me = document.currentScript, src = (me && me.src || '').replace(/[^/]*$/, '') + 'painting.webp';
  d.classList.add('sf-backdrop');
  var s = document.createElement('style');
  s.textContent =
    'html.sf-backdrop{--bd-m:clamp(10px,3.4vw,48px);background:#2a251f url("' + src + '") center/cover fixed!important;min-height:100%}' +
    'html.sf-backdrop>body{box-sizing:border-box;margin:var(--bd-m) auto!important;width:calc(100% - 2 * var(--bd-m));' +
    'min-height:calc(100vh - 2 * var(--bd-m));border-radius:clamp(10px,1.2vw,16px);overflow:clip;' +
    'box-shadow:0 34px 80px -28px rgba(12,10,7,.7),0 0 0 1px rgba(0,0,0,.1)}';
  (document.head || d).appendChild(s);
  // A page that painted its colour on <html> and left <body> clear keeps that colour on the sheet.
  function sheet() {
    var b = document.body; if (!b) return;
    if (getComputedStyle(b).backgroundColor.replace(/\s/g, '') !== 'rgba(0,0,0,0)') return;
    d.classList.remove('sf-backdrop');
    var c = getComputedStyle(d).backgroundColor;
    d.classList.add('sf-backdrop');
    b.style.backgroundColor = c.replace(/\s/g, '') === 'rgba(0,0,0,0)' ? '#fff' : c;
  }
  // A fixed bar across the top (or bottom) of the page stays on the sheet, not over the painting.
  var bars = [];
  function findBars() {
    var b = document.body; if (!b) return;
    bars = [];
    b.querySelectorAll('*').forEach(function (el) {
      var cs = getComputedStyle(el); if (cs.position !== 'fixed') return;
      var r = el.getBoundingClientRect();
      if (r.width >= innerWidth * 0.9 && r.height < innerHeight * 0.4) bars.push({el: el, top: r.top < innerHeight / 2});
    });
    place();
  }
  function place() {
    if (!bars.length) return;
    var m = parseFloat(getComputedStyle(document.body).marginLeft) || 0;
    var below = d.scrollHeight - scrollY - innerHeight;
    bars.forEach(function (x) {
      var s = x.el.style; s.left = m + 'px'; s.right = m + 'px'; s.width = 'auto';
      if (x.top) s.top = Math.max(0, m - scrollY) + 'px'; else s.bottom = Math.max(0, m - below) + 'px';
    });
  }
  function ready() { sheet(); findBars(); }
  document.addEventListener('DOMContentLoaded', ready);
  addEventListener('load', ready);
  addEventListener('scroll', place, {passive: true});
  addEventListener('resize', findBars);
})();

/* StyleFeatures scaffolds: shared runtime. Safe to load twice.
   - [data-reveal] fades in on scroll
   - .ph-video gets a play/pause button, a running timeline and a timecode, so a video slot behaves like one
     (data-dur="12" seconds, data-autoplay for background loops)
   - press N (or ?clean in the URL) to hide the notes */
if (!window.__sfScaffold) {
  window.__sfScaffold = true;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } }),
    { rootMargin: '0px 0px -8% 0px', threshold: 0.06 });
  const PLAY = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 3.8v12.4L16 10z" fill="currentColor"/></svg>';
  const PAUSE = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5.5 4h3v12h-3zM11.5 4h3v12h-3z" fill="currentColor"/></svg>';
  const fmt = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

  function video(el) {
    if (el.__sf) return; el.__sf = true;
    const dur = +el.dataset.dur || 12, loop = el.hasAttribute('data-autoplay') || el.hasAttribute('data-loop');
    const btn = document.createElement('button');
    btn.className = 'ph-play'; btn.type = 'button'; btn.setAttribute('aria-label', 'Play video'); btn.innerHTML = PLAY;
    const bar = document.createElement('div'); bar.className = 'ph-bar'; bar.setAttribute('aria-hidden', 'true');
    bar.innerHTML = `<span class="t">0:00</span><span class="ph-track"><i></i></span><span>${fmt(dur)}</span>`;
    if (el.hasAttribute('data-nobar')) bar.hidden = true;
    if (el.hasAttribute('data-nobutton')) btn.hidden = true;
    el.append(btn, bar);
    const t = bar.querySelector('.t');
    let pos = 0, playing = false, last = 0, raf = 0, visible = true;
    const draw = () => { el.style.setProperty('--p', pos / dur); t.textContent = fmt(pos); el.style.setProperty('--sf-t', pos); };
    const tick = (now) => {
      if (!playing) return;
      pos += Math.min(.1, (now - last) / 1000); last = now;
      if (pos >= dur) { if (loop) pos = 0; else { pos = dur; set(false); } }
      draw(); el.dispatchEvent(new CustomEvent('sf:time', { detail: { t: pos, dur } }));
      if (visible) raf = requestAnimationFrame(tick);
    };
    function set(on) {
      playing = on; el.classList.toggle('is-playing', on);
      btn.innerHTML = on ? PAUSE : PLAY; btn.setAttribute('aria-label', on ? 'Pause video' : 'Play video');
      cancelAnimationFrame(raf);
      if (on) { if (pos >= dur) pos = 0; last = performance.now(); raf = requestAnimationFrame(tick); }
    }
    btn.addEventListener('click', (e) => { e.stopPropagation(); set(!playing); });
    el.sfVideo = { play: () => set(true), pause: () => set(false), seek: (s) => { pos = Math.max(0, Math.min(dur, s)); draw(); }, get t() { return pos; }, dur };
    new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible && playing) { last = performance.now(); cancelAnimationFrame(raf); raf = requestAnimationFrame(tick); } }).observe(el);
    if (el.hasAttribute('data-autoplay') && !reduce) set(true);
    draw();
  }

  const scan = (root = document) => {
    root.querySelectorAll('[data-reveal]:not(.is-in)').forEach((el) => (reduce ? el.classList.add('is-in') : io.observe(el)));
    root.querySelectorAll('.ph-video').forEach(video);
  };
  window.sfScan = scan;
  window.sfVideo = video;
  const boot = () => scan();
  if (document.readyState === 'loading') addEventListener('DOMContentLoaded', boot); else boot();
  if (location.search.includes('clean')) document.documentElement.classList.add('sf-clean');
  if (location.search.includes('thumb')) document.documentElement.classList.add('sf-thumb');
  if (innerWidth < 700) addEventListener('DOMContentLoaded', () => document.querySelector('.sf-spec')?.classList.add('is-min'));
  addEventListener('keydown', (e) => { if (e.key === 'n' && !/INPUT|TEXTAREA/.test(document.activeElement?.tagName)) document.documentElement.classList.toggle('sf-clean'); });
  const down = () => document.documentElement.classList.toggle('is-down', scrollY > 24);
  addEventListener('scroll', down, { passive: true }); down();
}

// demo/office-hours: book a call.
//   the week      the diary fills in from the coming week (or data-week="YYYY-MM-DD" on the root: its Monday) before the
//                 film is measured: dates, the week's title and number, the little month in the margin, the slip and
//                 the invite card. Times shorter than the film's offer get .is-short, so they fade when it's picked.
//   the film      tour.js on the play driver; it starts once it's on screen and plays once. Reduced motion shows the
//                 week with the entry written in. ?record films it once; ?t=12 freezes a moment (../tour/README.md).
//   your turn     an open time or an offer in the diary, clicked, takes the visitor to the booking with it chosen.
//   the booking   the offer picker, both time zones with live clocks (data-tz on the root: your IANA zone, e.g.
//                 "Europe/Lisbon"; empty means the visitor's own), your scheduler's embed (data-embed / data-embed-0..2
//                 on .oh-embed) and an email fallback that carries the offer and the time.
import { Tour } from '../tour/tour.js';
import script, { FILM_OFFER } from './script.js';

const q = new URLSearchParams(location.search);
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const fmt = (d, o) => new Intl.DateTimeFormat('en-GB', o).format(d);

export default function init(root) {
  const off = [];
  const week = fillWeek(root);
  const film = root.querySelector('.oh-film');
  let tour = null;
  if (film) { const r = diary(root, film); tour = r.tour; off.push(r.off); }
  const book = root.querySelector('.oh-book');
  if (book) off.push(booking(root, book, week, tour));
  off.push(rules(root));
  return () => off.forEach((f) => f && f());
}

/* ── the coming week ── */
function monday(root) {
  const set = root.dataset.week;
  if (set && /^\d{4}-\d{2}-\d{2}$/.test(set)) { const [y, m, d] = set.split('-').map(Number); const t = new Date(y, m - 1, d); t.setDate(t.getDate() - ((t.getDay() + 6) % 7)); return t; }
  const t = new Date(); t.setHours(0, 0, 0, 0);
  const dow = (t.getDay() + 6) % 7;                       // 0 = Monday
  t.setDate(t.getDate() + (dow === 0 ? 0 : 7 - dow));     // today if it's Monday, otherwise next Monday
  return t;
}
function isoWeek(d) {
  const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate())); const n = t.getUTCDay() || 7;
  t.setUTCDate(t.getUTCDate() + 4 - n); const y0 = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  return Math.ceil(((t - y0) / 864e5 + 1) / 7);
}
function fillWeek(root) {
  const mon = monday(root), day = (i) => { const d = new Date(mon); d.setDate(d.getDate() + i); return d; };
  root.querySelectorAll('[data-oh-date]').forEach((b) => { b.textContent = day(+b.dataset.ohDate).getDate(); });
  root.querySelectorAll('[data-oh-weekof]').forEach((e) => { e.textContent = fmt(mon, { day: 'numeric', month: 'long' }); });
  root.querySelectorAll('[data-oh-weekno]').forEach((e) => { e.textContent = 'Week ' + isoWeek(mon); });
  // the booked day: the column the film's slot sits in
  const slot = root.querySelector('[data-tour="slot-thu"]'), di = +(slot?.closest('.oh-col')?.dataset.d ?? 3), bd = day(di);
  const time = slot?.querySelector(':scope > b')?.textContent || '10:00';
  root.querySelectorAll('[data-oh-when="long"]').forEach((e) => { e.textContent = `${DAYS[di]} ${fmt(bd, { day: 'numeric', month: 'long' })}`; });
  root.querySelectorAll('[data-oh-when="short"]').forEach((e) => { e.textContent = `${DAYS[di].slice(0, 3)} ${bd.getDate()}, ${time}`; });
  root.querySelectorAll('[data-oh-month]').forEach((e) => { e.textContent = fmt(bd, { month: 'long', year: 'numeric' }); });
  // the little month in the margin: Monday first, the week ringed, a dot on the booked day (the film shows it)
  const cal = root.querySelector('.oh-cal');
  if (cal) {
    const first = new Date(bd.getFullYear(), bd.getMonth(), 1), lead = (first.getDay() + 6) % 7, n = new Date(bd.getFullYear(), bd.getMonth() + 1, 0).getDate();
    const cells = ['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((c) => `<b>${c}</b>`);
    for (let i = 0; i < lead; i++) cells.push('<span class="is-out">.</span>');
    const inWeek = (k) => { const d = new Date(bd.getFullYear(), bd.getMonth(), k); return d >= mon && d <= day(4); };
    for (let k = 1; k <= n; k++) cells.push(`<span${inWeek(k) ? ' class="is-wk"' : ''}>${k}</span>`);
    const at = lead + bd.getDate() - 1, row = Math.floor(at / 7) + 1;
    cal.innerHTML = cells.join('') +
      `<i class="oh-cal-band" style="top:${row * 22}px"></i><i class="oh-cal-dot" data-tour="cal-dot" style="left:${(at % 7) * 26}px;top:${row * 22}px"></i>`;
  }
  // times too short for the film's offer fade when it's picked
  const len = +(root.querySelector(`[data-tour="${FILM_OFFER}"]`)?.dataset.len || 45);
  root.querySelectorAll('.oh-slot[data-m]').forEach((s) => s.classList.toggle('is-short', +s.dataset.m < len));
  // time zone labels
  const tz = zoneOf(root);
  if (!root.dataset.tzLabel) root.querySelectorAll('[data-oh-tz]').forEach((e) => { if (/your city/i.test(e.textContent) && root.dataset.tz) e.textContent = city(tz); });
  return { mon, day, tz };
}
const zoneOf = (root) => root.dataset.tz || Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
const city = (tz) => (tz.split('/').pop() || tz).replace(/_/g, ' ') + ' time';
function offsetMin(tz, d = new Date()) {
  try {
    const v = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'longOffset' }).formatToParts(d).find((p) => p.type === 'timeZoneName')?.value || 'GMT';
    const m = v.match(/([+-])(\d{1,2}):?(\d{2})?/); return m ? (m[1] === '-' ? -1 : 1) * (+m[2] * 60 + +(m[3] || 0)) : 0;
  } catch { return 0; }
}

/* ── the diary film, and the diary as the visitor's after it ── */
function diary(root, film) {
  const tour = new Tour(film, script);
  film.tour = tour;
  const off = [() => tour.destroy()];
  if (tour.still && !q.has('t') && tour.api.marks.still != null) tour.render(tour.api.marks.still, true);
  if (tour.rec) return { tour, off: () => off.forEach((f) => f()) };

  if (!tour.still) {
    let mine = false, wait = 0;
    const own = (e) => { if (e.target.closest?.('.tour-ctl')) mine = true; };
    film.addEventListener('pointerdown', own); off.push(() => film.removeEventListener('pointerdown', own));
    const io = new IntersectionObserver(([e]) => {
      clearTimeout(wait);
      if (e.intersectionRatio >= .45 && !mine && !tour.begun) wait = setTimeout(() => tour.begin(), 700);
    }, { threshold: [0, .45] });
    io.observe(film); off.push(() => { io.disconnect(); clearTimeout(wait); });
  }

  // your turn: an open time or an offer in the diary goes to the booking with it chosen
  const win = film.querySelector('[data-tour-window]');
  const pick = (e) => {
    const s = e.target.closest('.oh-slot[data-open]'), o = e.target.closest('.oh-offer');
    if (!s && !o) return;
    if (tour.playing) tour.pause();
    root.dispatchEvent(new CustomEvent('oh:pick', { detail: s ? { slot: s } : { offer: [...root.querySelectorAll('.oh-offer')].indexOf(o) } }));
  };
  win?.addEventListener('click', pick); off.push(() => win?.removeEventListener('click', pick));
  return { tour, off: () => off.forEach((f) => f()) };
}

/* ── the booking ── */
function booking(root, book, week, tour) {
  const off = [];
  const btns = [...book.querySelectorAll('.oh-pick [role=radio]')];
  const embed = book.querySelector('.oh-embed'), mail = book.querySelector('[data-oh-mail]'), chosenEl = book.querySelector('[data-oh-chosen]');
  const names = [...root.querySelectorAll('.oh-offer')].map((o) => o.dataset.name);
  const to = (mail?.getAttribute('href') || '').replace(/^mailto:/, '');
  let offer = Math.max(0, btns.findIndex((b) => b.getAttribute('aria-checked') === 'true')), slot = null;

  const url = (i) => embed?.getAttribute(`data-embed-${i}`) || embed?.dataset.embed || '';
  const showEmbed = () => {
    const u = url(offer); if (!embed || !u) return;
    let f = embed.querySelector('iframe');
    if (!f) { embed.innerHTML = ''; f = document.createElement('iframe'); f.title = 'Book a time'; f.loading = 'lazy'; embed.append(f); }
    if (f.getAttribute('src') !== u) f.src = u;
  };
  const mailto = () => {
    if (!mail) return;
    const myTz = week.tz, yourTz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const lines = [`I'd like to book: ${names[offer] || ''}`];
    if (slot) lines.push(`The time I picked: ${slot} (${city(myTz)})`); else lines.push('Two times that suit me: ');
    lines.push(`My time zone: ${yourTz}`, '', 'What it\'s about: ');
    mail.href = `mailto:${to}?subject=${encodeURIComponent('Booking: ' + (names[offer] || 'a call'))}&body=${encodeURIComponent(lines.join('\n'))}`;
  };
  const choose = (i, focus) => {
    offer = i;
    btns.forEach((b, k) => { b.setAttribute('aria-checked', k === i); b.tabIndex = k === i ? 0 : -1; });
    if (focus) btns[i].focus();
    showEmbed(); mailto(); say();
  };
  const say = () => {
    if (!chosenEl) return;
    chosenEl.hidden = !slot; if (slot) chosenEl.textContent = `${names[offer] || ''}, ${slot}`;
  };
  const onClick = (e) => { const b = e.target.closest('.oh-pick [role=radio]'); if (b) choose(btns.indexOf(b)); };
  const onKey = (e) => {
    const i = btns.indexOf(document.activeElement); if (i < 0) return;
    if (['ArrowDown', 'ArrowRight', 'ArrowUp', 'ArrowLeft'].includes(e.key)) { e.preventDefault(); choose((i + (/Down|Right/.test(e.key) ? 1 : btns.length - 1)) % btns.length, true); }
  };
  book.addEventListener('click', onClick); book.addEventListener('keydown', onKey);
  off.push(() => { book.removeEventListener('click', onClick); book.removeEventListener('keydown', onKey); });

  // "Book this" on an offer, or a time / an offer clicked in the diary
  const go = () => book.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'start' });
  const fromLink = (e) => { const a = e.target.closest('.oh-off-book[data-offer]'); if (!a) return; e.preventDefault(); choose(+a.dataset.offer); go(); };
  root.addEventListener('click', fromLink); off.push(() => root.removeEventListener('click', fromLink));
  const fromDiary = (e) => {
    const d = e.detail || {};
    if (d.slot) {
      const di = +(d.slot.closest('.oh-col')?.dataset.d ?? 0), date = week.day(di);
      slot = `${DAYS[di]} ${fmt(date, { day: 'numeric', month: 'long' })} at ${d.slot.querySelector(':scope > b')?.textContent || ''}`;
      const m = +d.slot.dataset.m || 0, fit = [...root.querySelectorAll('.oh-offer')].map((o) => +o.dataset.len || 0);
      if ((fit[offer] || 0) > m) { const k = fit.findIndex((l) => l <= m); if (k >= 0) offer = k; }
      choose(offer);
    } else if (d.offer >= 0) choose(d.offer);
    go();
  };
  root.addEventListener('oh:pick', fromDiary); off.push(() => root.removeEventListener('oh:pick', fromDiary));

  // the two clocks, and the gap between them
  const myTz = week.tz, yourTz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
  const tick = () => {
    const now = new Date(), hm = (tz) => { try { return fmt(now, { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz }); } catch { return '--:--'; } };
    book.querySelectorAll('[data-oh-now="you"]').forEach((e) => { e.textContent = hm(yourTz); });
    book.querySelectorAll('[data-oh-now="me"]').forEach((e) => { e.textContent = hm(myTz); });
    const gap = offsetMin(myTz, now) - offsetMin(yourTz, now), h = Math.abs(gap) / 60, hs = `${Number.isInteger(h) ? h : h.toFixed(1)} hour${h === 1 ? '' : 's'}`;
    const g = book.querySelector('[data-oh-gap]');
    if (g) g.textContent = gap === 0 ? 'We keep the same time. The times in my diary are yours too.' : `I'm ${hs} ${gap > 0 ? 'ahead of' : 'behind'} you. The booking page shows every time in yours.`;
  };
  book.querySelectorAll('[data-oh-zone="you"]').forEach((e) => { e.textContent = yourTz.replace(/_/g, ' '); });
  tick(); const iv = setInterval(tick, 15000); off.push(() => clearInterval(iv));

  choose(offer);
  return () => off.forEach((f) => f());
}

/* the offers' hour rules ink themselves in as they arrive */
function rules(root) {
  const rs = [...root.querySelectorAll('.oh-rule i')];
  if (!rs.length || reduce || q.has('record')) return null;
  rs.forEach((r) => r.style.setProperty('--k', 0));
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.style.setProperty('--k', 1); io.unobserve(e.target); } }), { rootMargin: '0px 0px -15% 0px' });
  rs.forEach((r) => io.observe(r));
  return () => io.disconnect();
}

/* tour.js: a declarative product-tour engine. The shared foundation for every StyleFeatures demo film.
   Full reference: README.md beside this file. In short:

     import { Tour, click, type, show, zoom, chapter } from './tour.js';
     new Tour(rootElement, { size: [1200, 750], steps: [ chapter('01 / 03', 'Start <em>here</em>', 'One line.'),
                                                        click('@new'), show('@modal'), type('@name', 'Hello') ] });

   Everything on screen is a pure function of one number, t (seconds). Each frame the engine works out the
   product's state at t (classes, attributes, text, CSS variables, scroll positions), the camera, the fake
   cursor and the overlays, and writes only what changed. So any moment can be rendered on its own:
   ?t=12.5 freezes there, seek(t) jumps there, and a scroll, a clock or a screen recorder can all drive it.

   Selectors ('@name' is short for [data-tour="name"]) are measured against the product as it is at the moment
   each step happens, and measured again whenever the layout changes (fonts, resize, your CSS), so editing the
   product never breaks the script. */

const cl = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
export const ease = (t) => t * t * t * (t * (t * 6 - 15) + 10);           // smootherstep: settles, no overshoot
const lerp = (a, b, t) => a + (b - a) * t;
const rnd = (n) => { const x = Math.sin(n * 91.7 + 13.1) * 43758.5453; return x - Math.floor(x); };
const sel = (s) => (typeof s === 'string' ? s.replace(/@([\w-]+)/g, '[data-tour="$1"]') : s);
const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

/* ── step builders ─────────────────────────────────────────────────────────────────────────────
   Pointer steps run one after another on the script's clock. Side steps (zoom, show, hide, set, tween,
   chapter, caption) start at the current moment and let the next step start with them.
   Any step takes { at: seconds } to pin it, { wait: seconds } to start later, { parallel: true }
   so a pointer step doesn't hold up the next one, { block: true } so a side step does. */
export const move = (to, o = {}) => ({ ...o, do: 'move', to });
export const click = (to, o = {}) => ({ ...o, do: 'click', to });
export const dblclick = (to, o = {}) => ({ ...o, do: 'dblclick', to });
export const hover = (to, o = {}) => ({ ...o, do: 'hover', to });
export const type = (el, text, o = {}) => ({ ...o, do: 'type', el, text });
export const drag = (handle, o = {}) => ({ ...o, do: 'drag', handle });
export const scroll = (el, to, o = {}) => ({ ...o, do: 'scroll', el, to });
export const key = (keys, o = {}) => ({ ...o, do: 'key', keys: [].concat(keys) });
export const zoom = (to, z = 'fit', o = {}) => ({ ...o, do: 'zoom', to, z });
export const unzoom = (o = {}) => ({ ...o, do: 'zoom', to: null, z: 1 });
export const show = (el, o = {}) => ({ ...o, do: 'show', el });
export const hide = (el, o = {}) => ({ ...o, do: 'hide', el });
export const set = (el, changes, o = {}) => ({ ...o, do: 'set', el, changes });
export const tween = (el, prop, from, to, o = {}) => ({ ...o, do: 'tween', el, prop, from, to });
export const chapter = (n, title, line = '', o = {}) => ({ ...o, do: 'chapter', n, title, line });
export const caption = (text, o = {}) => ({ ...o, do: 'caption', text });
export const pause = (dur = 1) => ({ do: 'pause', dur });
export const stream = (el, o = {}) => ({ ...o, do: 'stream', el });   // reveal matches one after another, like output arriving
export const tap = click;                                                 // the same step; reads better in a touch film
export const longpress = (to, o = {}) => ({ ...o, do: 'longpress', to }); // press and hold; it fires after { hold } s
export const swipe = (on, o = {}) => ({ ...o, do: 'swipe', on });         // a finger flick: { by, scroll } or { prop, from, to } (README)
export const mark = (name, o = {}) => ({ ...o, do: 'mark', name });       // a named moment: tour.api.marks[name] is its time, and the list is in order (README)

/* eases for show / hide / tween: { ease: 'out' | 'ios' | 'spring' | (t) => t }. Default: smootherstep.
   'ios' is a critically damped spring (UIKit pushes and sheets), 'spring' overshoots by about 3%. */
export const eases = {
  linear: (t) => t,
  out: (t) => 1 - Math.pow(1 - t, 3),
  ios: (t) => (t >= 1 ? 1 : (1 - (1 + 9 * t) * Math.exp(-9 * t)) / (1 - 10 * Math.exp(-9))),
  spring: (t) => (t >= 1 ? 1 : 1 - Math.exp(-6 * t) * (Math.cos(5.3 * t) + 1.13 * Math.sin(5.3 * t))),
};
const easeOf = (e) => (typeof e === 'function' ? e : eases[e] || ease);

/* when each character of a typed string lands. rhythm: undefined (even, as before) | 'human' (beats between
   words, a reach for symbols, the odd hesitation) | 'stream' (chunks, like a model's reply arriving) */
function keyTimes(txt, cps, seed, rhythm, c) {
  const at = [], b = 1 / cps;
  if (rhythm === 'stream') {
    for (let i = 0, j = 0; i < txt.length; j++) { const n = 1 + Math.floor(rnd(seed * 13 + j) * 5); c += b * n * (.5 + rnd(seed * 29 + j)); for (let m = 0; m < n && i < txt.length; m++, i++) at.push(c); }
    return at;
  }
  for (let i = 0; i < txt.length; i++) {
    let d = b * (.55 + .9 * rnd(seed * 31 + i));
    if (rhythm === 'human') {
      const ch = txt[i], pv = txt[i - 1] || '';
      if (pv === ' ') d += b * (.3 + .9 * rnd(seed * 37 + i));
      if (/[-/.:=_@|&>~"'`]/.test(ch)) d += b * .7;
      if (/[,;!?]/.test(pv) || (pv === '.' && ch === ' ')) d += b * 1.4;
      if (ch === pv && /\w/.test(ch)) d *= .6;
      if (i > 2 && rnd(seed * 43 + i) < .035) d += .2 + .25 * rnd(seed * 47 + i);
    }
    c += d; at.push(c);
  }
  return at;
}

/* load harvested fragments: <div data-tour-include="fragments/home.html"></div>. Await it before new Tour(). */
export async function include(root) {
  await Promise.all([...root.querySelectorAll('[data-tour-include]')].map(async (el) => {
    const r = await fetch(el.dataset.tourInclude); el.innerHTML = r.ok ? await r.text() : ''; el.removeAttribute('data-tour-include');
    if (!r.ok) console.warn('[tour] could not load', r.url);
  }));
}

/* ?record for a page with several tours in one frame (demo/versus, demo/deck): makes el the record stage, the box
   of ?ratio= centred on near-black with the rest of the page hidden, exactly as a single film gets it. Build each
   Tour inside it with { record: 'page' } and drive them from the page. Returns { w, h, ratio } and keeps it current. */
export function recordStage(el, q = new URLSearchParams(location.search)) {
  document.documentElement.classList.add('tour-record', 'sf-clean');
  el.setAttribute('data-tour-root', ''); el.classList.add('is-record');
  const r = (q.get('ratio') || '16:9').split(':').map(Number), box = { w: 0, h: 0, ratio: r.join(':') };
  const fit = () => {
    let w = innerWidth, h = innerHeight;
    if (r.length === 2 && r[0] > 0) { const a = r[0] / r[1]; if (w / h > a) w = Math.round(h * a); else h = Math.round(w / a); }
    box.w = w; box.h = h; el.style.setProperty('--rw', w + 'px'); el.style.setProperty('--rh', h + 'px');
  };
  fit(); addEventListener('resize', fit);
  return box;
}

const BLOCKS = new Set(['move', 'click', 'dblclick', 'hover', 'type', 'drag', 'scroll', 'key', 'pause', 'stream', 'longpress', 'swipe']);
const POINT = new Set(['move', 'click', 'dblclick', 'hover', 'drag', 'longpress', 'swipe']);

/* ── window chromes ─────────────────────────────────────────────────────────────────────────── */
const CHROME = {
  browser: (w) => `<div class="tour-chrome" data-kind="browser"><span class="tour-lights"><i></i><i></i><i></i></span>
    <span class="tour-navs"><svg viewBox="0 0 16 16"><path d="M10 3 5 8l5 5"/></svg><svg viewBox="0 0 16 16"><path d="m6 3 5 5-5 5"/></svg></span>
    <span class="tour-url"><svg viewBox="0 0 16 16"><path d="M5 7V5a3 3 0 0 1 6 0v2M4 7h8v6H4z"/></svg>${w.dataset.url || 'yourproduct.com'}</span>
    <span class="tour-navs is-end"><svg viewBox="0 0 16 16"><path d="M8 3v7M5 6l3-3 3 3M3 9v4h10V9"/></svg><svg viewBox="0 0 16 16"><path d="M8 3v10M3 8h10"/></svg></span></div>`,
  app: (w) => `<div class="tour-chrome" data-kind="app"><span class="tour-lights"><i></i><i></i><i></i></span><b>${w.dataset.title || ''}</b></div>`,
  terminal: (w) => `<div class="tour-chrome" data-kind="terminal"><span class="tour-lights"><i></i><i></i><i></i></span><b>${w.dataset.title || ''}</b></div>`,
  phone: () => `<div class="tour-chrome" data-kind="phone"><b>9:41</b><span class="tour-notch"></span><span class="tour-status"><i></i><i></i><i></i></span></div>`,
  none: () => '',
};

/* ── cursor art (hotspot at 0,0) ─────────────────────────────────────────────────────────────── */
const CURSORS = `
<svg class="tour-arrow" width="22" height="30" viewBox="-1 -1 16 23"><path d="M0 0V16.6L4.3 12.6L7.2 19.4L10 18.2L7.2 11.6H13Z" stroke-linejoin="round"/></svg>
<svg class="tour-hand" width="24" height="26" viewBox="0 0 20 22"><path d="M7 1.4c.9 0 1.6.7 1.6 1.6V9h.3V7.5c0-.8.7-1.4 1.5-1.4s1.5.6 1.5 1.4v1.9h.3V8.3c0-.8.7-1.4 1.5-1.4s1.5.6 1.5 1.4v1.5h.3v-.6c0-.8.6-1.3 1.3-1.3.8 0 1.4.6 1.4 1.3V15c0 3.4-2.5 6-5.8 6h-1.6c-2 0-3.4-.8-4.6-2.3l-4.1-5.1c-.6-.7-.5-1.7.2-2.2.7-.5 1.6-.4 2.2.2l.7.9V3c0-.9.7-1.6 1.6-1.6Z" stroke-linejoin="round"/></svg>
<svg class="tour-beam" width="10" height="24" viewBox="0 0 10 24"><path d="M2 1.5h2.2c.5 0 .8.3.8.8v19.4c0 .5-.3.8-.8.8H2M8 1.5H5.8c-.5 0-.8.3-.8.8v19.4c0 .5.3.8.8.8H8M3 12h4" fill="none" stroke-linecap="round"/></svg>`;

export class Tour {
  constructor(root, script, o = {}) {
    this.root = root; this.S = script; this.o = o; root.setAttribute('data-tour-root', '');
    const q = new URLSearchParams(location.search), d = root.dataset;
