        case 'zoom': this.zooms.push({ start, dur: st.dur ?? 1.3, el: st.to ? this.one(st.to) : null, z: st.z, fill: st.fill ?? .66, aim: st.aim || [.5, .5], max: st.max ?? 2.6, arc: st.arc || 0, pt: null, size: null }); end = start + (st.dur ?? 1.3); break;
        case 'show': case 'hide': {
