      * (L.stack ? cl(1 - Math.max(L.F.y - sp[1], sp[1] - L.F.y - L.F.h) / 24) : 1);   // stacked: never drawn outside the window's frame
      this.cur.style.opacity = co.toFixed(3); this._sp = sp; this._co = co;
