    this.fade(this.card, this.chapters, t, (c) => { this.card.children[0].textContent = c.n; this.card.children[1].innerHTML = c.title; this.card.children[2].innerHTML = c.line; this.card.children[2].hidden = !c.line; this.capTop(); });
