    const KEYS = new Set([' ', 'PageDown', 'PageUp', 'ArrowDown', 'ArrowUp', 'Home', 'End']);
    const onKey = (e) => { if (KEYS.has(e.key) && !e.target?.closest?.('input, textarea, select, button, [contenteditable]')) { block(e); hold(e); } };
